// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }

    function testFuzz_property(address recipient, uint amount, address secondRecipient, uint secondAmount) public {
        vm.assume(recipient != address(0));
        vm.assume(secondRecipient != address(0));

        c.newGrantProposal(recipient, amount);
        uint countAfterFirst = c.proposalCount();

        c.newGrantProposal(secondRecipient, secondAmount);
        uint countAfterSecond = c.proposalCount();

        assertTrue(
            countAfterSecond == countAfterFirst + 1,
            "each new grant proposal must increment the proposal counter by one"
        );
    }
}
